llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C41"],
      "claim": "Verapamil, a dimethoxyphenyl tertiary amine structurally related to the query, showed 52.3% absolute oral bioavailability in cirrhotic patients, supporting high F for this scaffold despite disease-related first-pass changes.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "In normal subjects, the (+)-isomer of verapamil had a mean absolute bioavailability of 50%, and the (-)-isomer 20%, both at or above the F≥20% threshold, providing condition-relevant support for high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Noscapine, a dimethoxy-substituted isoquinoline alkaloid, has a measured absolute oral bioavailability of 30% in humans, directly supporting F≥20% for a structurally related dimethoxy-containing alkaloid.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Valbenazine, a dimethoxy tetrahydroisoquinoline, has an absolute oral bioavailability of approximately 49% in humans, supporting high F for the query's dimethoxy-substituted ring system.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Colchicine, a polymethoxy amide-containing alkaloid, has a mean absolute oral bioavailability of about 55% in elderly subjects, supporting high F for a similar poly-methoxy, amide-containing scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Clomipramine, a tricyclic antidepressant with a tertiary amine side chain, has an absolute oral bioavailability of approximately 50% in humans, supporting high F for the query's basic tertiary amine and lipophilic ring system.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple structurally related dimethoxy-substituted alkaloids and basic amines (verapamil, noscapine, valbenazine, colchicine, clomipramine) have measured absolute oral bioavailability of 30-55%, all above the 20% threshold. The most transferable analogues support high F; low-F records are confounded by rifampicin induction or have very low transferability. Physicochemical properties are mixed but not disqualifying.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule.",
    "The highest-transfer verapamil data are from cirrhotic patients, which may overestimate F relative to healthy subjects.",
    "No data on the query's P-glycoprotein efflux or first-pass metabolism.",
    "The query's low neutral fraction (0.02) may limit passive absorption, but this is not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

